# Hypothesis: on the (worst-group, mean) trade-off, E1+fc-correction dominates fc-correction-only; estimate P(pass) per candidate/bias with practice + test sampling uncertainty.
NT = np.array([2255, 2255, 642, 642])
rng_mc = np.random.RandomState(123)
def p_pass(counts_correct, n=np.array([467,466,133,133]), nsim=20000, rng=rng_mc):
    k = np.asarray(counts_correct)
    p = rng.beta(k+1, n-k+1, size=(nsim,4))
    acc = rng.binomial(NT, p)/NT
    return np.mean((acc.min(1)>=0.88) & (acc@GW>=0.94))
def p_pass_margin(s, shift):
    pred = (s+shift)>0
