        res.append((sh, np.mean(pp), np.mean(aa,0)))
    best = max(res, key=lambda r: r[1])
    print('%-40s best shift %+.2f P(pass) %.3f groups %s wmean %.2f | at 0: P %.3f %s' % (name, best[0], best[1], np.round(best[2],1), GW@best[2],
