def oof_fcproj_general(Fx, w, b0, probe_fn, scale=1.0, reps=4, k=5, seed=0):
    out = np.zeros((reps, N))
    for r in range(reps):
        for tr, te in StratifiedKFold(k, shuffle=True, random_state=seed+r).split(Fx, g):
            dp, db_, u, mub = probe_fn(Fx[tr], g[tr]); beta = scale*(w@dp)
            out[r, te] = Fx[te]@(w - beta*u) + b0 + beta*(u@mub)
    return out
