# Hypothesis: ridge-10 probe at layer4.1 is much more precise in-sample than out-of-fold (optimism), whereas min-norm / ridge>=100 probes are not.
def insample_dprime(fn, X):
    dp_, db__, v_, mub_ = fn(X, g); s = (X-mub_)@v_
    ms = [s[g==k].mean() for k in range(4)]; sds = [s[g==k].std() for k in range(4)]
    return (np.mean(ms[1::2])-np.mean(ms[0::2]))/np.mean(sds), 100*np.mean((s>0)==place)
def oof_dprime(fn, X, seed=0):
    s = np.zeros(N)
    for tr, te in StratifiedKFold(5, shuffle=True, random_state=seed).split(X, g):
        dp_, db__, v_, mub_ = fn(X[tr], g[tr]); s[te] = (X[te]-mub_)@v_
    ms = [s[g==k].mean() for k in range(4)]; sds = [s[g==k].std() for k in range(4)]
    return (np.mean(ms[1::2])-np.mean(ms[0::2]))/np.mean(sds), 100*np.mean((s>0)==place)
